package patterns.creational;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class Builder {
public enum HttpMethod{GET,POST,PUT,PATCH,DELETE}public record HttpRequest(HttpMethod method,String url,Map<String,String> headers,String body,long timeoutMs){public HttpRequest{headers=Collections.unmodifiableMap(new LinkedHashMap<>(headers));}}public static class HttpRequestBuilder{private HttpMethod method=HttpMethod.GET;private String baseUrl="",body;private long timeoutMs=30000;private final List<String> query=new ArrayList<>();private final Map<String,String> headers=new LinkedHashMap<>();public static HttpRequestBuilder get(String url){return new HttpRequestBuilder().url(url);}public static HttpRequestBuilder post(String url){return new HttpRequestBuilder().url(url).withMethod(HttpMethod.POST);}public HttpRequestBuilder url(String url){baseUrl=url;return this;}public HttpRequestBuilder withMethod(HttpMethod method){this.method=method;return this;}public HttpRequestBuilder header(String name,String value){headers.put(name.toLowerCase(Locale.ROOT),value);return this;}public HttpRequestBuilder param(String name,Object value){query.add(java.net.URLEncoder.encode(name,java.nio.charset.StandardCharsets.UTF_8)+"="+java.net.URLEncoder.encode(String.valueOf(value),java.nio.charset.StandardCharsets.UTF_8));return this;}public HttpRequestBuilder json(Object payload){body=shared.Json.stringify(payload);return header("content-type","application/json");}public HttpRequestBuilder timeout(long ms){timeoutMs=ms;return this;}public HttpRequest build(){if(baseUrl.isEmpty())throw new IllegalStateException("URL is required");if(body!=null&&method==HttpMethod.GET)throw new IllegalStateException("GET request cannot have a body");return new HttpRequest(method,baseUrl+(query.isEmpty()?"":"?"+String.join("&",query)),headers,body,timeoutMs);}}
}
